(() => {
  'use strict';
  const canvas = document.querySelector('#game'), ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const ui = { build:$('#build-panel'), attack:$('#attack-panel'), list:$('#piece-list'), title:$('#mission-title'), hint:$('#mission-hint'), eyebrow:$('#phase-eyebrow'), icon:$('#mission-icon'), round:$('#round-label'), score:$('#score'), ammo:$('#ammo-count'), birds:$('#ammo-birds'), toast:$('#toast'), result:$('#result-modal') };
  const defs = [
    {id:'plank',name:'Timber',count:8,w:2.6,h:.43,color:'#d69554',dark:'#a86d3e',mass:1},
    {id:'pillar',name:'Pillar',count:4,w:.56,h:1.75,color:'#c88b50',dark:'#9c6437',mass:1.4},
    {id:'stone',name:'Stone',count:3,w:1.05,h:1.05,color:'#8999a9',dark:'#657487',mass:2.6},
    {id:'glass',name:'Glass',count:4,w:2.15,h:.38,color:'#7bcbd3',dark:'#4e9eaf',mass:.65}
  ];
  let W=0,H=0,dpr=1,scale=40,groundY=0,phase='build',selected='plank',rotated=false,blocks=[],birdsLeft=3,score=0,shot=null,aim=null,dragging=null,toastTimer=0,gameOver=false,lastTime=0,ambience=0,soundOn=false,pointer=null;
  const sling={x:-6.9,y:2.05}, pig={x:5.8,y:.46,alive:true,hit:false};
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const def=(id)=>defs.find(d=>d.id===id);
  function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);scale=Math.min(W/19.5,H/11.5);groundY=H*(W<640?.705:.735);}
  function project(x,y){return {x:W/2+x*scale,y:groundY-y*scale};}
  function unproject(px,py){return {x:(px-W/2)/scale,y:(groundY-py)/scale};}
  function makeBlock(id,x,y,angle=0){const d=def(id);return {id,x,y,w:d.w,h:d.h,angle,color:d.color,dark:d.dark,mass:d.mass,vx:0,vy:0,spin:0,active:false,settled:false};}
  function updatePieceUI(){ui.list.innerHTML='';defs.forEach(d=>{const b=document.createElement('button');b.className='piece-card'+(selected===d.id?' selected':'');b.disabled=d.count===0;b.innerHTML=`<span class="piece-count">×${d.count}</span><span class="piece-art"><span class="piece-shape ${d.id}"></span></span><span class="piece-name">${d.name}</span>`;b.addEventListener('click',()=>{selected=d.id;updatePieceUI();});ui.list.appendChild(b);});}
  function updateAmmo(){ui.ammo.textContent=`${birdsLeft} LEFT`;ui.birds.innerHTML='';for(let i=0;i<3;i++){const b=document.createElement('span');b.className='ammo-bird'+(i>=birdsLeft?' spent':'');ui.birds.appendChild(b);}}
  function setPhase(next){phase=next;ui.build.classList.toggle('hidden',next!=='build');ui.attack.classList.toggle('hidden',next!=='attack');if(next==='build'){ui.round.textContent='YOUR TURN';ui.eyebrow.textContent='BUILDER PHASE';ui.title.textContent='Build your fort';ui.hint.textContent='Stack a clever defense. Your friend is ready to launch!';ui.icon.textContent='🛠️';}else{ui.round.textContent='ATTACK PHASE';ui.eyebrow.textContent='FRIEND’S TURN';ui.title.textContent='Take your best shot';ui.hint.textContent='Pull back on the bird, aim for the pig, and let fly.';ui.icon.textContent='🎯';updateAmmo();}}
  function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),1900);}
  function newGame(){blocks=[];defs.forEach(d=>d.count=({plank:8,pillar:4,stone:3,glass:4}[d.id]));birdsLeft=3;score=0;ui.score.textContent='0';pig.alive=true;pig.hit=false;pig.x=5.8;shot=null;gameOver=false;ui.result.classList.add('hidden');selected='plank';rotated=false;setPhase('build');updatePieceUI();}
  function drawBackground(t){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#83c8eb');g.addColorStop(.58,'#b7e5ef');g.addColorStop(1,'#e1f1dc');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    const sun=project(7.5,8.5);ctx.fillStyle='#fff3c780';ctx.beginPath();ctx.arc(sun.x,sun.y,scale*.76,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#a5d9d4';ctx.beginPath();ctx.moveTo(0,groundY);for(let x=0;x<=W+20;x+=20){const y=groundY-scale*(1.15+Math.sin(x*.006+1)*.52+Math.sin(x*.013)*.2);ctx.lineTo(x,y);}ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.closePath();ctx.fill();
    ctx.fillStyle='#82c7a6';ctx.beginPath();ctx.moveTo(0,groundY+scale*.05);for(let x=0;x<=W+20;x+=20){ctx.lineTo(x,groundY+scale*(.18+Math.sin(x*.009+2)*.34+Math.sin(x*.018)*.13));}ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.closePath();ctx.fill();
    for(let i=0;i<3;i++){const x=((W*(.18+i*.36)+t*(5+i*2))%(W+180))-80,y=H*(.2+i*.075),r=scale*.2;ctx.fillStyle='#ffffff72';ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.arc(x+r*.75,y-r*.25,r*.78,0,7);ctx.arc(x+r*1.35,y,r*.58,0,7);ctx.fill();}
    const floor=project(0,0);ctx.fillStyle='#7dbc72';ctx.fillRect(0,floor.y,W,H-floor.y);const fg=ctx.createLinearGradient(0,floor.y,0,H);fg.addColorStop(0,'#98ce78');fg.addColorStop(1,'#70b665');ctx.fillStyle=fg;ctx.fillRect(0,floor.y,W,H-floor.y);ctx.fillStyle='#d3e39a';ctx.fillRect(0,floor.y,W,Math.max(3,scale*.12));ctx.strokeStyle='#6bab69';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,floor.y+scale*.12);ctx.lineTo(W,floor.y+scale*.12);ctx.stroke();
    for(let i=0;i<22;i++){let x=(i*127+31)%W,y=floor.y+scale*(.5+((i*37)%95)/100);if(y<H-12){ctx.fillStyle=i%3?'#d9ed9b':'#f8e5a0';ctx.beginPath();ctx.arc(x,y,1.5+(i%2),0,7);ctx.fill();}}
  }
  function drawBlock(b,ghost=false){const p=project(b.x,b.y),w=b.w*scale,h=b.h*scale;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(-b.angle);if(!ghost){ctx.fillStyle='#334a5030';ctx.beginPath();ctx.ellipse(0,h*.53,w*.55,Math.max(3,scale*.11),0,0,Math.PI*2);ctx.fill();}const depth=Math.max(4,scale*.13);ctx.fillStyle=b.dark;ctx.beginPath();ctx.moveTo(-w/2,-h/2);ctx.lineTo(-w/2+depth,-h/2-depth);ctx.lineTo(w/2+depth,-h/2-depth);ctx.lineTo(w/2,-h/2);ctx.closePath();ctx.fill();ctx.fillStyle=ghost?`${b.color}88`:b.color;ctx.fillRect(-w/2,-h/2,w,h);ctx.fillStyle=ghost?'#ffffff4d':'#ffffff34';ctx.fillRect(-w/2+2,-h/2+2,w-4,Math.max(2,h*.11));ctx.fillStyle=ghost?'#ffffff28':'#00000012';ctx.fillRect(-w/2,-h*.02,w,h*.52);ctx.strokeStyle=ghost?'#ffffffad':'#76563c55';ctx.lineWidth=1;ctx.strokeRect(-w/2,-h/2,w,h);if(b.id==='stone'){ctx.strokeStyle='#ffffff28';ctx.beginPath();ctx.moveTo(-w*.26,-h*.22);ctx.lineTo(-w*.05,-h*.02);ctx.lineTo(w*.1,-h*.18);ctx.stroke();}if(b.id==='glass'){ctx.strokeStyle='#ffffffa3';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-w*.34,-h*.12);ctx.lineTo(w*.26,-h*.12);ctx.stroke();}ctx.restore();}
  function drawSling(){const p=project(sling.x,sling.y);ctx.save();ctx.lineCap='round';ctx.strokeStyle='#956037';ctx.lineWidth=scale*.13;ctx.beginPath();ctx.moveTo(p.x-scale*.23,p.y+scale*.65);ctx.lineTo(p.x-scale*.1,p.y-scale*.48);ctx.lineTo(p.x+scale*.15,p.y+scale*.65);ctx.stroke();ctx.strokeStyle='#704c35';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(p.x-scale*.1,p.y-scale*.45);ctx.lineTo((aim?aim.x:p.x)+scale*.2,(aim?aim.y:p.y));ctx.moveTo(p.x+scale*.15,p.y-scale*.32);ctx.lineTo((aim?aim.x:p.x)+scale*.2,(aim?aim.y:p.y));ctx.stroke();ctx.restore();}

function drawBird(x,y,r=scale*.28){const p=project(x,y);ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#d95345';ctx.beginPath();ctx.ellipse(-r*.1,r*.08,r,r*.86,-.18,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ed6b58';ctx.beginPath();ctx.ellipse(-r*.15,-r*.12,r*.77,r*.59,-.3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f7f0dd';ctx.beginPath();ctx.ellipse(r*.2,r*.18,r*.42,r*.33,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(r*.27,-r*.2,r*.2,0,7);ctx.arc(r*.65,-r*.13,r*.17,0,7);ctx.fill();ctx.fillStyle='#20344a';ctx.beginPath();ctx.arc(r*.32,-r*.19,r*.07,0,7);ctx.arc(r*.68,-r*.12,r*.065,0,7);ctx.fill();ctx.fillStyle='#f4bf57';ctx.beginPath();ctx.moveTo(r*.76,r*.04);ctx.lineTo(r*1.27,r*.2);ctx.lineTo(r*.76,r*.34);ctx.closePath();ctx.fill();ctx.fillStyle='#8c403a';ctx.beginPath();ctx.moveTo(-r*.42,-r*.62);ctx.lineTo(-r*.08,-r*1.14);ctx.lineTo(r*.05,-r*.55);ctx.fill();ctx.restore();}
function drawPig(){if(!pig.alive)return;const p=project(pig.x,pig.y),r=scale*.36;ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#538f65';ctx.beginPath();ctx.ellipse(0,r*.58,r*.7,r*.22,0,0,7);ctx.fill();ctx.fillStyle='#8fd083';ctx.beginPath();ctx.arc(0,0,r,0,7);ctx.fill();ctx.fillStyle='#a5df94';ctx.beginPath();ctx.arc(-r*.55,-r*.66,r*.35,0,7);ctx.arc(r*.55,-r*.66,r*.35,0,7);ctx.fill();ctx.fillStyle='#dcf4c8';ctx.beginPath();ctx.ellipse(0,r*.28,r*.44,r*.29,0,0,7);ctx.fill();ctx.fillStyle='#6bab75';ctx.beginPath();ctx.ellipse(-r*.14,r*.26,r*.07,r*.11,0,0,7);ctx.ellipse(r*.14,r*.26,r*.07,r*.11,0,0,7);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(-r*.25,-r*.25,r*.16,0,7);ctx.arc(r*.25,-r*.25,r*.16,0,7);ctx.fill();ctx.fillStyle='#223d45';ctx.beginPath();ctx.arc(-r*.22,-r*.23,r*.06,0,7);ctx.arc(r*.28,-r*.23,r*.06,0,7);ctx.fill();ctx.strokeStyle='#4b7656';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,r*.16,r*.19,.15,Math.PI-.15);ctx.stroke();ctx.restore();}
function drawTrajectory(){if(!aim||!dragging)return;const dx=sling.x-aim.x,dy=sling.y-aim.y,vx=dx*1.65,vy=dy*1.65;ctx.fillStyle='#fffdf1a8';for(let i=1;i<=12;i++){const t=i*.095,x=sling.x+vx*t,y=sling.y+vy*t-.5*9.8*t*t;if(y<.3)break;const p=project(x,y);ctx.beginPath();ctx.arc(p.x,p.y,Math.max(1.5,4-i*.2),0,7);ctx.fill();}}
function drawScene(t){drawBackground(t);drawSling();const base=project(5.8,0);ctx.fillStyle='#729a6c';ctx.fillRect(base.x-scale*2.35,base.y-scale*.025,scale*4.8,scale*.06);blocks.forEach(b=>drawBlock(b));if(phase==='build'&&selected){const d=def(selected),m=pointer?unproject(pointer.x,pointer.y):{x:5.8,y:.8},b=makeBlock(selected,clamp(m.x,-2,9),Math.max(d.h/2,m.y),rotated?Math.PI/2:0);if(pointer)b.y=Math.max(d.h/2,(groundY-pointer.y)/scale);drawBlock(b,true);}drawPig();if(aim&&dragging)drawTrajectory();if(shot)drawBird(shot.x,shot.y);else if(phase==='attack'&&birdsLeft>0){if(dragging)drawBird(aim.x,aim.y);else drawBird(sling.x,sling.y);}if(phase==='build')for(let i=0;i<3;i++){const p=project(sling.x-.42-i*.34,.35);ctx.fillStyle='#d7594a';ctx.beginPath();ctx.arc(p.x,p.y,scale*.105,0,7);ctx.fill();}}
function pointerPos(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top};}
function addAt(px,py){const p=unproject(px,py),d=def(selected);if(!d||d.count<=0)return;const angle=rotated?Math.PI/2:0,b=makeBlock(selected,clamp(p.x,-2.5,9),Math.max(d.h/2,p.y),angle);if(isOverlapping(b)){toast('That spot is already taken');return;}blocks.push(b);d.count--;updatePieceUI();rotated=false;}
function isOverlapping(b){for(const o of blocks){const dx=Math.abs(b.x-o.x),dy=Math.abs(b.y-o.y);if(dx<(b.w+o.w)*.46&&dy<(b.h+o.h)*.46)return true;}return false;}
function hitBlock(x,y){for(let i=blocks.length-1;i>=0;i--){const b=blocks[i];if(Math.abs(x-b.x)<b.w*.6&&Math.abs(y-b.y)<b.h*.65)return i;}return -1;}
canvas.addEventListener('pointermove',e=>{pointer=pointerPos(e);if(phase==='attack'&&dragging){const p=unproject(pointer.x,pointer.y);aim={x:clamp(p.x,sling.x-2.25,sling.x+.05),y:clamp(p.y,.45,sling.y+1.5)};}});
canvas.addEventListener('pointerdown',e=>{pointer=pointerPos(e);canvas.setPointerCapture(e.pointerId);const p=unproject(pointer.x,pointer.y);if(phase==='build'){const i=hitBlock(p.x,p.y);if(i>=0){const b=blocks.splice(i,1)[0];def(b.id).count++;updatePieceUI();return;}}if(phase==='attack'&&!shot&&birdsLeft>0&&Math.hypot(p.x-sling.x,p.y-sling.y)<1.15){dragging=true;aim={x:sling.x,y:sling.y};}});
canvas.addEventListener('pointerup',()=>{if(phase==='build'){if(pointer&&pointer.y<groundY-scale*.25)addAt(pointer.x,pointer.y);return;}if(phase==='attack'&&dragging){const dx=sling.x-aim.x,dy=sling.y-aim.y,power=Math.hypot(dx,dy);dragging=false;if(power<.18){aim=null;return;}shot={x:sling.x,y:sling.y,vx:dx*2.12,vy:dy*2.12};birdsLeft--;updateAmmo();aim=null;playSound(440,.07);}});
function playSound(freq=300,duration=.08){if(!soundOn)return;try{const ac=playSound.ac||(playSound.ac=new(window.AudioContext||window.webkitAudioContext)()),o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.055,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+duration);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+duration);}catch(_){}}
function attack(){if(!blocks.length){toast('Build a fort first!');return;}setPhase('attack');toast('Your friend has 3 shots — defend that pig!');}
$('#attack-btn').addEventListener('click',attack);$('#undo-btn').addEventListener('click',()=>{if(blocks.length){const b=blocks.pop();def(b.id).count++;updatePieceUI();}});$('#rebuild-btn').addEventListener('click',()=>newGame());$('#again-btn').addEventListener('click',()=>newGame());$('#sound-btn').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♩';e.currentTarget.setAttribute('aria-label',soundOn?'Mute sound':'Enable sound');playSound(520,.1);});
window.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='r'&&phase==='build'){rotated=!rotated;toast(rotated?'Piece rotated':'Piece horizontal');}if(e.key==='Escape'&&phase==='attack'&&!shot)setPhase('build');});

  function physics(dt){if(!shot)return;const s=shot,step=Math.min(dt,.035);s.vy-=9.8*step;s.x+=s.vx*step;s.y+=s.vy*step;s.vx*=Math.pow(.995,step*60);if(s.y<.3){s.y=.3;s.vy=Math.abs(s.vy)*.38;s.vx*=.77;if(Math.abs(s.vy)<1.2)s.vy=0;}for(const b of blocks){const dx=s.x-b.x,dy=s.y-b.y;if(Math.abs(dx)<b.w*.52+.32&&Math.abs(dy)<b.h*.55+.29){const impulse=Math.hypot(s.vx,s.vy);b.vx+=Math.sign(dx||1)*(s.vx*.48+Math.sign(dx||1)*impulse*.12)/b.mass;b.vy+=(s.vy*.5+Math.max(1,impulse*.07))/b.mass;b.spin+=rand(-1,1)*impulse*.012;b.active=true;s.vx*=.55;s.vy*=.48;if(impulse>4&&!b.hit){b.hit=true;score++;ui.score.textContent=score;playSound(210,.1);}if(impulse>14&&Math.random()<.14){b.vx+=rand(-2,2);b.vy+=rand(1,4);}break;}}if(pig.alive&&Math.hypot(s.x-pig.x,s.y-pig.y)<.64){pig.alive=false;score+=2;ui.score.textContent=score;playSound(180,.18);toast('Direct hit! The pig is down!');}if(s.x>10||s.x<-10||s.y<.2&&Math.abs(s.vx)<1.3)shot=null;}
  function settleBlocks(dt){for(let i=0;i<blocks.length;i++){const b=blocks[i];if(!b.active&&!b.settled)continue;b.vy-=9.8*dt;b.x+=b.vx*dt;b.y+=b.vy*dt;b.angle+=b.spin*dt;b.vx*=Math.pow(.97,dt*60);b.spin*=Math.pow(.93,dt*60);if(b.y<b.h/2){b.y=b.h/2;b.vy=Math.abs(b.vy)*.22;b.vx*=.75;b.spin*=.55;if(Math.abs(b.vy)<.7){b.vy=0;b.settled=true;}}for(let j=0;j<blocks.length;j++){if(i===j)continue;const o=blocks[j],dx=b.x-o.x,dy=b.y-o.y,overX=(b.w+o.w)*.43-Math.abs(dx),overY=(b.h+o.h)*.43-Math.abs(dy);if(overX>0&&overY>0&&Math.abs(b.angle)<.5&&Math.abs(o.angle)<.5){if(dy<0){b.y-=overY;b.vy=Math.max(0,b.vy);b.vx+=o.vx*.1;b.settled=true;}else{b.y+=overY;b.vy=Math.max(0,b.vy);}}}if(Math.abs(b.vx)<.08&&Math.abs(b.vy)<.15&&Math.abs(b.spin)<.15){b.vx=0;b.vy=0;b.spin=0;b.active=false;b.settled=true;}}}
  function endTurn(){if(gameOver)return;gameOver=true;setTimeout(()=>{if(!pig.alive){$('#result-emoji').textContent='🏆';$('#result-eyebrow').textContent='FORT FRIENDS CHAMPION';$('#result-title').textContent='Pig down!';$('#result-copy').textContent=`A perfect hit. You scored ${score} points!`;}else{$('#result-emoji').textContent=score>2?'💥':'🐷';$('#result-eyebrow').textContent=score>2?'GOOD DAMAGE':'THE PIG SURVIVED';$('#result-title').textContent=score>2?'Fort in pieces!':'Try another design';$('#result-copy').textContent=score>2?`You hit ${score} blocks. Can you do better?`:'A stronger tower might protect your friend next time.';}ui.result.classList.remove('hidden');},650);}
  function frame(now){const dt=Math.min(.035,(now-lastTime)/1000||.016);lastTime=now;ambience+=dt;physics(dt);settleBlocks(dt);drawScene(ambience);if(phase==='attack'&&!gameOver&&!dragging&&!shot&&birdsLeft===0)endTurn();requestAnimationFrame(frame);}
  resize();window.addEventListener('resize',resize);updatePieceUI();setPhase('build');requestAnimationFrame(frame);
})();

