  function drawTrajectory(){if(!aim||!dragging)return;const dx=sling.x-aim.x,dy=sling.y-aim.y,vx=dx*1.65,vy=dy*1.65;ctx.fillStyle='#fffdf1a8';for(let i=1;i<=12;i++){const t=i*.095,x=sling.x+vx*t,y=sling.y+vy*t-.5*9.8*t*t;if(y<.3)break;const p=project(x,y);ctx.beginPath();ctx.arc(p.x,p.y,Math.max(1.5,4-i*.2),0,7);ctx.fill();}}
  function drawScene(t){drawBackground(t);drawSling();const base=project(5.8,0);ctx.fillStyle='#729a6c';ctx.fillRect(base.x-scale*2.35,base.y-scale*.025,scale*4.8,scale*.06);blocks.forEach(b=>drawBlock(b));if(phase==='build'&&selected){const d=def(selected),m=pointer?unproject(pointer.x,pointer.y):{x:5.8,y:.8},b=makeBlock(selected,clamp(m.x,-2,9),Math.max(d.h/2,m.y),rotated?Math.PI/2:0);if(pointer)b.y=Math.max(d.h/2,(groundY-pointer.y)/scale);drawBlock(b,true);}drawPig();if(aim&&dragging)drawTrajectory();if(shot)drawBird(shot.x,shot.y);else if(phase==='attack'&&birdsLeft>0){if(dragging)drawBird(aim.x,aim.y);else drawBird(sling.x,sling.y);}if(phase==='build')for(let i=0;i<3;i++){const p=project(sling.x-.42-i*.34,.35);ctx.fillStyle='#d7594a';ctx.beginPath();ctx.arc(p.x,p.y,scale*.105,0,7);ctx.fill();}}
  function pointerPos(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top};}
  function addAt(px,py){const p=unproject(px,py),d=def(selected);if(!d||d.count<=0)return;const b=makeBlock(selected,clamp(p.x,-2.5,9),Math.max(d.h/2,p.y),rotated?Math.PI/2:0);if(isOverlapping(b)){toast('That spot is already taken');return;}blocks.push(b);d.count--;updatePieceUI();rotated=false;}
  function isOverlapping(b){for(const o of blocks){const dx=Math.abs(b.x-o.x),dy=Math.abs(b.y-o.y);if(dx<(b.w+o.w)*.46&&dy<(b.h+o.h)*.46)return true;}return false;}
  function hitBlock(x,y){for(let i=blocks.length-1;i>=0;i--){const b=blocks[i];if(Math.abs(x-b.x)<b.w*.6&&Math.abs(y-b.y)<b.h*.65)return i;}return -1;}
  canvas.addEventListener('pointermove',e=>{pointer=pointerPos(e);if(phase==='attack'&&dragging){const p=unproject(pointer.x,pointer.y);aim={x:clamp(p.x,sling.x-2.25,sling.x+.05),y:clamp(p.y,.45,sling.y+1.5)};}});
  canvas.addEventListener('pointerdown',e=>{pointer=pointerPos(e);canvas.setPointerCapture(e.pointerId);const p=unproject(pointer.x,pointer.y);if(phase==='build'){const i=hitBlock(p.x,p.y);if(i>=0){const b=blocks.splice(i,1)[0];def(b.id).count++;updatePieceUI();return;}}if(phase==='attack'&&!shot&&birdsLeft>0&&Math.hypot(p.x-sling.x,p.y-sling.y)<1.15){dragging=true;aim={x:sling.x,y:sling.y};}});
  canvas.addEventListener('pointerup',()=>{if(phase==='build'){if(pointer&&pointer.y<groundY-scale*.25)addAt(pointer.x,pointer.y);return;}if(phase==='attack'&&dragging){const dx=sling.x-aim.x,dy=sling.y-aim.y,power=Math.hypot(dx,dy);dragging=false;if(power<.18){aim=null;return;}shot={x:sling.x,y:sling.y,vx:dx*2.12,vy:dy*2.12};birdsLeft--;updateAmmo();aim=null;playSound(440,.07);}});
  function playSound(freq=300,duration=.08){if(!soundOn)return;try{const ac=playSound.ac||(playSound.ac=new(window.AudioContext||window.webkitAudioContext)()),o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.055,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+duration);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+duration);}catch(_){}}
  function attack(){if(!blocks.length){toast('Build a fort first!');return;}setPhase('attack');toast('Your friend has 3 shots — defend that pig!');}
  $('#attack-btn').addEventListener('click',attack);$('#undo-btn').addEventListener('click',()=>{if(blocks.length){const b=blocks.pop();def(b.id).count++;updatePieceUI();}});$('#rebuild-btn').addEventListener('click',()=>newGame());$('#again-btn').addEventListener('click',()=>newGame());$('#sound-btn').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♩';e.currentTarget.setAttribute('aria-label',soundOn?'Mute sound':'Enable sound');playSound(520,.1);});
  window.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='r'&&phase==='build'){rotated=!rotated;toast(rotated?'Piece rotated':'Piece horizontal');}if(e.key==='Escape'&&phase==='attack'&&!shot)setPhase('build');});
  function physics(dt){if(!shot)return;const s=shot,step=Math.min(dt,.035);s.vy-=9.8*step;s.x+=s.vx*step;s.y+=s.vy*step;s.vx*=Math.pow(.995,step*60);if(s.y<.3){s.y=.3;s.vy=Math.abs(s.vy)*.38;s.vx*=.77;if(Math.abs(s.vy)<1.2)s.vy=0;}for(const b of blocks){const dx=s.x-b.x,dy=s.y-b.y;if(Math.abs(dx)<b.w*.52+.32&&Math.abs(dy)<b.h*.55+.29){const impulse=Math.hypot(s.vx,s.vy);b.vx+=Math.sign(dx||1)*(s.vx*.48+Math.sign(dx||1)*impulse*.12)/b.mass;b.vy+=(s.vy*.5+Math.max(1,impulse*.07))/b.mass;b.spin+=rand(-1,1)*impulse*.012;b.active=true;s.vx*=.55;s.vy*=.48;if(impulse>4&&!b.hit){b.hit=true;score++;ui.score.textContent=score;playSound(210,.1);}break;}}if(pig.alive&&Math.hypot(s.x-pig.x,s.y-pig.y)<.64){pig.alive=false;score+=2;ui.score.textContent=score;playSound(180,.18);toast('Direct hit! The pig is down!');}if(s.x>10||s.x<-10||s.y<.2&&Math.abs(s.vx)<1.3)shot=null;}
  function settleBlocks(dt){for(let i=0;i<blocks.length;i++){const b=blocks[i];if(!b.active&&!b.settled)continue;b.vy-=9.8*dt;b.x+=b.vx*dt;b.y+=b.vy*dt;b.angle+=b.spin*dt;b.vx*=Math.pow(.97,dt*60);b.spin*=Math.pow(.93,dt*60);if(b.y<b.h/2){b.y=b.h/2;b.vy=Math.abs(b.vy)*.22;b.vx*=.75;b.spin*=.55;if(Math.abs(b.vy)<.7){b.vy=0;b.settled=true;}}for(let j=0;j<blocks.length;j++){if(i===j)continue;const o=blocks[j],dx=b.x-o.x,dy=b.y-o.y,overX=(b.w+o.w)*.43-Math.abs(dx),overY=(b.h+o.h)*.43-Math.abs(dy);if(overX>0&&overY>0&&Math.abs(b.angle)<.5&&Math.abs(o.angle)<.5&&dy<0){b.y-=overY;b.vy=Math.max(0,b.vy);b.vx+=o.vx*.1;b.settled=true;}}if(Math.abs(b.vx)<.08&&Math.abs(b.vy)<.15&&Math.abs(b.spin)<.15){b.vx=0;b.vy=0;b.spin=0;b.active=false;b.settled=true;}}}
  function endTurn(){if(gameOver)return;gameOver=true;setTimeout(()=>{if(!pig.alive){$('#result-emoji').textContent='🏆';$('#result-eyebrow').textContent='FORT FRIENDS CHAMPION';$('#result-title').textContent='Pig down!';$('#result-copy').textContent=`A perfect hit. You scored ${score} points!`;}else{$('#result-emoji').textContent=score>2?'💥':'🐷';$('#result-eyebrow').textContent=score>2?'GOOD DAMAGE':'THE PIG SURVIVED';$('#result-title').textContent=score>2?'Fort in pieces!':'Try another design';$('#result-copy').textContent=score>2?`You hit ${score} blocks. Can you do better?`:'A stronger tower might protect your friend next time.';}ui.result.classList.remove('hidden');},650);}
  function frame(now){const dt=Math.min(.035,(now-lastTime)/1000||.016);lastTime=now;ambience+=dt;physics(dt);settleBlocks(dt);drawScene(ambience);if(phase==='attack'&&!gameOver&&!dragging&&!shot&&birdsLeft===0)endTurn();requestAnimationFrame(frame);}
  resize();window.addEventListener('resize',resize);updatePieceUI();setPhase('build');requestAnimationFrame(frame);
})();

